	is_triggered_only = yes

	trigger = {
		is_merc_enclave_founding_allowed = yes
	}

	immediate = {
		set_event_locked = yes
	}

	option = {
		name = DEAL
		custom_tooltip = "enclave.2.a.tooltip"
		allow = {
			is_merc_enclave_founding_allowed = yes
			owner = {
				if = {
					limit = {
						country_uses_bio_ships = yes
					}
