				}
				resource_stockpile_compare = { resource = alloys value >= 2000 }
				resource_stockpile_compare = { resource = influence value >= 100 }
			}
		}
		owner = {
			if = {
				limit = {
					country_uses_bio_ships = yes
				}
				add_resource = {
					food = -1500
				}
			}
			else = {
			add_resource = {
				energy = -1500
				}
			}
			add_resource = {
				alloys = -2000
				influence = -100
			}
		}

		hidden_effect = {
			owner = {
				set_country_flag = tutorial_met_mercenary_enclave
				set_country_flag = formed_mercenaries
			}
			fleet_event = { id = enclave.21 }
		}

		ai_chance = {
			factor = 10
			modifier = {
				factor = 0
				owner = {
					is_fanatic_pacifist = yes
				}
			}
			modifier = {
				factor = 0.1
				owner = {
					has_ethic = ethic_pacifist
				}
			}
			modifier = {
				factor = 5
				owner = {
					has_ethic = ethic_militarist
				}
			}
			modifier = {
				factor = 10
				owner = {
					has_ethic = ethic_fanatic_militarist
				}
			}
			modifier = {
				factor = 5
				owner = {
					is_megacorp = yes
				}
			}
		}
	}

	option = {
		name = NODEAL

		ai_chance = {
			factor = 5
			modifier = {
				factor = 0.1
				owner = {
					is_militarist = yes
					is_fanatic_pacifist = no
				}
			}
		}
	}

	abort_trigger = {
		owner = {
			has_origin = origin_mindwardens
		}
	}

	after = {
		hidden_effect = {
			set_event_locked = no
		}
