script:
country_event = {
	id = enclave.275
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		#Check who owns the system the enclave is in and register them as the target for the payment event.
		random_owned_fleet = {
			limit = {
				is_ship_size = enclave_mercenary_station
			}
			solar_system = {
				if = {
					limit = {
						exists = space_owner
					}
					space_owner = {
						save_event_target_as = mercenary_patron
					}
				}
				if = {
					limit = {
						any_starbase_in_system = {
							is_waystation_starbase = yes
							owner = { is_nomadic = yes }
						}
					}
					random_starbase_in_system = {
						limit = {
							is_waystation_starbase = yes
							owner = { is_nomadic = yes }
						}
						owner = { save_event_target_as = mercenary_nomad_patron }
					}
				}
			}
		}
		root = {
			save_event_target_as = mercenary_enclave_country
		}
		if = {
			limit = {
				exists = event_target:mercenary_patron
			}
			event_target:mercenary_patron = {
				random_list = {
					32 = { country_event = { id = enclave.2000 } }
					32 = { country_event = { id = enclave.2005 } }
					32 = { country_event = { id = enclave.2010 } }
					2 = { country_event = { id = enclave.2020 } }
					2 = { country_event = { id = enclave.2025 } }
				}
			}
		}
		if = {
			limit = {
				exists = event_target:mercenary_nomad_patron
			}
			event_target:mercenary_nomad_patron = {
				random_list = {
					32 = { country_event = { id = enclave.2000 } }
					32 = { country_event = { id = enclave.2005 } }
					32 = { country_event = { id = enclave.2010 } }
					2 = { country_event = { id = enclave.2020 } }
					2 = { country_event = { id = enclave.2025 } }
				}
			}
		}
	}

	after = {
		start_situation = {
			type = mercenary_dividends
			target = root
		}
		destroy_situation = from
	}
}

