		}
		text = enclave.5505.gestalt.desc
	}
	picture = GFX_evt_ghost_ship
	show_sound = event_wind_ruins
	location = root
	situation = event_target:divination_situation
	is_triggered_only = yes

	trigger = {
		exists = owner
	}

	immediate = {
		create_ambient_object = {
			type = shattered_frontier_ship
			location = root
		}
		last_created_ambient_object = {
			set_location = {
				target = root
				angle = 135
			}
			set_ambient_object_flag = shattered_frontier_object
			save_event_target_as = shattered_frontier_ship
		}
		create_ambient_object = {
			type = psi_storm_1
			location = root
		}
		last_created_ambient_object = {
			set_ambient_object_flag = shattered_frontier_object
			save_event_target_as = shattered_frontier_storm
			set_location = {
				target = prev
				distance = 0
				angle = random
			}
		}
		if = {
			limit = { has_moon = yes }
			every_moon = {
				limit = {
					colonizable_planet = no
					NOR = {
						is_planet_class = pc_shattered
						habitable_planet = yes
						is_planet_class = pc_habitat
					}
				}
				clear_planet_modifiers = yes
				clear_deposits = yes
				change_pc = pc_shrouded
				save_event_target_as = shrouded_moon
			}
		}
	}

	#Continue investigating
	option = {
		name = enclave.5505.a
		trigger = {
			owner = { is_gestalt = no }
		}
		add_modifier = {
			modifier = shattered_frontier_storm_mod
			days = -1
		}
		hidden_effect = {
			carrier_event = {
				id = enclave.5510
				days = 40
				random = 20
			}
		}
	}
	option = {
		name = enclave.5505.gestalt.a
		trigger = {
			owner = { is_gestalt = yes }
		}
		add_modifier = {
			modifier = shattered_frontier_storm_mod
			days = -1
		}
		hidden_effect = {
			carrier_event = {
				id = enclave.5510
				days = 40
				random = 20
			}
		}
	}
	#Cease prodding!
	option = {
		name = enclave.5505.b
		trigger = {
			owner = { is_gestalt = no }
		}
		add_modifier = {
			modifier = shattered_frontier_storm_mod
			days = -1
		}
		hidden_effect = {
			carrier_event = {
				id = enclave.5506
				days = 20
				random = 20
			}
		}
	}
	option = {
		name = enclave.5505.b
		trigger = {
			owner = { is_gestalt = yes }
		}
		add_modifier = {
			modifier = shattered_frontier_storm_gestalt_mod
			days = -1
		}
		hidden_effect = {
			carrier_event = {
				id = enclave.5506
				days = 20
				random = 20
			}
		}
	}
}

