			progress = 0.6
		}
		add_modifier = {
			modifier = shroudwalker_zro_tithe
			days = -1
		}
		hidden_effect = {
			if = {
				limit = {
					is_nomadic = no
				}
				random_planet_within_border = {
					limit = {
						has_deposit = no
						has_anomaly = no
					}
					add_deposit = d_zro_deposit_1
				}
			}
			else = {
				random_owned_nonprimary_starbase = {
					limit = {
						is_waystation_starbase = yes
					}
					solar_system = {
						random_system_planet = {
							limit = {
								has_deposit = no
								has_anomaly = no
							}
							add_deposit = d_zro_deposit_1
						}
					}
				}
			}
			set_country_flag = purchased_zro_tech
			country_event = { id = enclave.7255 } # Post-Sale Message
		}
	}
	option = {
		name = GOODBYE
		default_hide_option = yes
	}
}

